import { Box, FillPreview } from '@wix/design-system';
import type { FC } from 'react';
import React from 'react';

import { resolveDocumentColorToCss } from './../theme-color-token.js';

type ColorSwatchProps = {
  colors: string[];
};

export const ColorSwatch: FC<ColorSwatchProps> = ({ colors }) => (
  <Box width="20px" height="20px" pointerEvents="none">
    <FillPreview
      fill={colors.map(color => resolveDocumentColorToCss(color) ?? color)}
      size="extraTiny"
      as="div"
      tabIndex={-1}
    />
  </Box>
);
