import { Box, FillPreview } from '@wix/design-system';
import React, { useContext, useMemo } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { resolveColorToDisplayHex } from './../resolve-color-to-display-hex.js';
import {
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

export type ShapeColorEntry = { originalColor: string; displayedColor: string };

type ShapeColorsModalProps = {
  colorMap: Record<string, string>;
  onClose: () => void;
  isColorPickerOpen: () => boolean;
  openColorPickerFor: (entry: ShapeColorEntry, containerEl: HTMLElement | null | undefined) => void;
  closeColorPicker: () => void;
};

export const ShapeColorsModal = ({
  colorMap,
  onClose,
  isColorPickerOpen,
  openColorPickerFor,
  closeColorPicker,
}: ShapeColorsModalProps) => {
  const { t } = useContext(RicosContext);
  const containerEl = usePanelContainerElement();

  const colorEntries = useMemo(
    () =>
      Object.entries(colorMap).map(([originalColor, customColor]) => ({
        originalColor,
        displayedColor: customColor || originalColor,
      })),
    [colorMap]
  );

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: () => {
      if (isColorPickerOpen()) {
        return;
      }
      onClose();
    },
  });

  const onColorClick = (entry: ShapeColorEntry) => {
    if (isColorPickerOpen()) {
      closeColorPicker();
      setTimeout(() => openColorPickerFor(entry, containerEl), 0);
    } else {
      openColorPickerFor(entry, containerEl);
    }
  };

  return (
    <Panel closeButtonProps={{ onClick: onClose }}>
      <PanelHeader title={t('Layout_SettingsModal_Tab_Design_Fill_Color')} />
      <Box
        paddingLeft="SP3"
        paddingRight="SP3"
        paddingTop="SP2"
        paddingBottom="SP2"
        direction="horizontal"
        gap="SP2"
        flexWrap="wrap"
      >
        {colorEntries.map(entry => (
          <Box key={entry.originalColor} height="32px" width="32px">
            <FillPreview
              fill={
                resolveColorToDisplayHex(entry.displayedColor, containerEl, {
                  preserveAlpha: true,
                }) ?? entry.displayedColor
              }
              onClick={() => onColorClick(entry)}
            />
          </Box>
        ))}
      </Box>
    </Panel>
  );
};
