import { TextButton } from '@wix/design-system';
import React, { useContext } from 'react';

import { parseLink } from './../../../ricos-content/lib/node-utils.js';
import type { IToolbarItem, RicosServices, ToolbarButton } from './../../../ricos-types/index.js';

import { LINK_PLUGIN_WEB_LINK_BUTTON } from '../../data-hooks.js';
import { EditorBaseUrlContext } from '../../editor-base-url/editor-base-url-context.js';
import { getEditableUrl } from '../../url/get-editable-url.js';
import { getHrefUrl } from '../../url/get-href-url.js';
import classes from './url-link-button-scss.js';

export const createUrlLinkButton = ({
  services,
  attributes,
}: {
  services: RicosServices;
  attributes: ToolbarButton['attributes'];
}): ToolbarButton => {
  return {
    id: 'urlLink',
    type: 'toggle',
    dataHook: LINK_PLUGIN_WEB_LINK_BUTTON,
    attributes,
    tooltip: null,
    // External toolbars draw this instead of calling the renderer, outside any ricos provider —
    // hence the base url off the services rather than off the React context.
    getIcon:
      ({ attributes }) =>
      () => (
        <ToolbarUrl link={attributes.selectedUrlLinkData} baseUrl={services.editorProps?.baseUrl} />
      ),
    renderer: toolbarItem => <UrlLinkButton toolbarItem={toolbarItem} />,
    command: () => {},
  };
};

const UrlLinkButton = ({ toolbarItem }: { toolbarItem: IToolbarItem }) => {
  const { baseUrl } = useContext(EditorBaseUrlContext);

  return (
    <div className={classes.toolbarUrlContainer}>
      <ToolbarUrl
        link={toolbarItem.attributes.selectedUrlLinkData}
        baseUrl={baseUrl}
        className={classes.toolbarUrl}
        dataHook={toolbarItem.presentation?.dataHook}
        tabIndex={toolbarItem.presentation.tabIndex}
      />
    </div>
  );
};

const ToolbarUrl = ({
  link,
  baseUrl,
  dataHook,
  className,
  tabIndex,
}: {
  link: Parameters<typeof parseLink>[0];
  baseUrl?: string;
  dataHook?: string;
  className?: string;
  tabIndex?: number;
}) => {
  const { url = '', rel = '', target = '_self' } = parseLink(link);

  return (
    <TextButton
      as="a"
      size="small"
      underline="onHover"
      // Clips a long url with an ellipsis against the container's max-width. The full url is
      // deliberately not offered as a WDS hover tooltip: the link toolbar floats, and today's
      // behaviour is a bare truncation.
      ellipsis
      showTooltip={false}
      className={className}
      dataHook={dataHook}
      href={getHrefUrl(url, baseUrl)}
      rel={rel}
      target={target}
      tabIndex={tabIndex}
      // Holds the editor's selection: without it, pressing the mouse here blurs ProseMirror
      // and the toolbar loses the link it is acting on.
      onMouseDown={event => event.preventDefault()}
    >
      {getEditableUrl(url, baseUrl)}
    </TextButton>
  );
};
